import java.util.*;
import static co.aplomo.web.Html.escapar;
/** RF-014 a RF-020: una foto y una conversación, con los campos y motor actuales. */
final class ConversacionEvaluacion {
 private ConversacionEvaluacion(){}
 static String nueva(Sesion s,Evaluaciones.Contexto c,int id){String aviso=c.visita().empresaNombre().equals(co.aplomo.servicio.PracticaEvaluacion.NOMBRE)?"<div class=\"banner\" role=\"status\">Evaluación de práctica · Los resultados se guardan en la empresa de demostración. Puedes usar las fotos de ejemplo.</div>":"";return pagina(s,c.puestos(),id,c.visita().visita().id(),c.visita().empresaNombre()+" · "+c.visita().salonNombre()).replace("<form data-evaluacion",aviso+"<form data-evaluacion");}
 private static String pagina(Sesion s,List<Puesto> puestos,int id,int visita,String lugar){
  var p=puestos.stream().filter(x->x.id()==id).findFirst().orElse(null);if(id!=0&&p==null)throw new IllegalArgumentException("Elige un puesto activo del salón de esta visita.");
  StringBuilder h=new StringBuilder("<div class=\"pagehead\"><div><span class=\"eyebrow\">Evaluaciones · Nueva</span><h1>Nueva evaluación</h1><p class=\"hint\">").append(escapar(lugar)).append("</p></div><span class=\"tag\" data-modo>").append(p==null?"":p.tipo().equals("ESCRITORIO")?"Oficina":"Planta").append("</span></div><form data-evaluacion data-revision=\"si\" data-conversacion=\"si\" data-tour=\"campo\" data-fases=\"7\" action=\"/evaluaciones\" method=\"post\" enctype=\"multipart/form-data\" novalidate>").append(Html.csrf(s));
  oculto(h,"cuenta_recuerdo",""+s.cuenta().id());oculto(h,"visita",""+visita);oculto(h,"recorrido","campo");for(String n:List.of("postura","motivo","criterio","minutos","condiciones_respondidas","carga_opcion"))oculto(h,n,"");
  if(p!=null)h.append("<input type=\"hidden\" name=\"puesto\" value=\"").append(id).append("\" data-tarea=\"").append(escapar(p.descripcion())).append("\">");else{h.append("<label>Puesto de trabajo<select class=\"input\" name=\"puesto\"><option value=\"\">Elige un puesto</option>");for(var q:puestos)h.append("<option value=\"").append(q.id()).append("\" data-tarea=\"").append(escapar(q.descripcion())).append("\">").append(escapar(q.descripcion())).append("</option>");h.append("</select></label>");}
  h.append("<header class=\"campo-cabecera\"><h2 data-titulo-fijo>Bienvenida y consentimiento</h2><div class=\"row between\"><button class=\"btn\" type=\"button\" data-atras-evaluacion>← Atrás</button><span id=\"pasoActual\" role=\"status\">Paso 1 de 7</span><strong data-lado-titulo></strong></div><ol class=\"campo-progreso\" aria-label=\"Pasos de la evaluación\">");String[] nombres={"Permiso","Conversación","Condiciones","Lado","Foto y ángulos","Carga","Resultado"};for(int i=0;i<7;i++)h.append("<li data-etapa=\"").append(i+1).append("\">").append(nombres[i]).append("</li>");h.append("</ol><progress max=\"7\" value=\"1\" aria-label=\"Avance de la evaluación\"></progress></header>");
  abrir(h,1,"Consentimiento");h.append(PaginasEvaluacion.opcion("acepta","si","Confirmo que la persona evaluada aceptó y firmó el consentimiento informado por escrito.","",true,"required",""));pregunta(h,"registro","","Permiso de fotos","",new String[][]{{"CON_FOTOS","Sí, permite fotos"},{"SIN_REGISTRO_FOTOGRAFICO","No permite fotos"}});h.append("</section>");
  abrir(h,2,"Conversación inicial");String[][] tiempos={{"MENOS_2","Menos de 2 horas"},{"DE_2_A_4","De 2 a 4 horas"},{"DE_4_A_6","Más de 4 y hasta 6"},{"DE_6_A_8","Más de 6 y hasta 8"},{"MAS_8","Más de 8 horas"}};for(var t:tiempos)t[0]=""+MapeosCampo.MINUTOS.get(t[0]);pregunta(h,"tiempo_campo","Pregúntale","¿Cuántas horas al día trabaja en este puesto?","",tiempos);
  String[][] momentos={{"EXIGENTE","Es el momento de mayor esfuerzo postural"},{"DURADERA","Es la postura que mantiene durante más tiempo"}};
  pregunta(h,"momento_campo","Pregúntale","¿En qué parte del trabajo se siente más incómodo o más cansado?","",momentos);
  pregunta(h,"duracion_campo","Pregúntale","¿Y cuál postura mantiene por más tiempo en el turno?","",new String[][]{{"MISMA","Es la misma"},momentos[0],momentos[1]});h.append("<p role=\"status\" data-misma hidden>Con una sola postura basta.</p></section>");
  abrir(h,3,"Condiciones del puesto");h.append("<div class=\"campo-condiciones\">");for(var x:PaginasEvaluacion.CONDICIONES)h.append(PaginasEvaluacion.opcion(x[0],"si",x[1],"",true,"",""));h.append(PaginasEvaluacion.opcion("ninguna","si","Ninguna","",true,"","")).append("</div>").append(Formularios.texto(Map.of(),"observaciones","Otras observaciones (opcional)",255,false)).append("</section>");
  abrir(h,4,"¿Qué lado del cuerpo trabaja más?");pregunta(h,"lado_recorrido","","¿Qué lado del cuerpo trabaja más?","",new String[][]{{"DERECHO","Derecho"},{"IZQUIERDO","Izquierdo"}});h.append("</section>");
  abrir(h,5,"Foto y ángulos");h.append("<div class=\"campo-dos-columnas\"><div class=\"campo-imagen\"><div data-muestra-perfil>").append(muestra("perfil","")).append("</div><div class=\"stack\" data-foto-revision hidden></div></div><div class=\"campo-panel\"><div data-subir-perfil><p>Fotografía a la persona de lado, con el cuerpo completo, en su postura real y con el brazo a la vista. Pon la cámara a la altura de la cadera.</p><p>Vamos a empezar con la foto de perfil. Después responderás la carga de esta postura.</p><button class=\"btn p\" type=\"button\" data-perfil>Subir foto</button>"+GaleriaDemo.selector("PERFIL")+"<input type=\"file\" hidden accept=\"image/jpeg,image/png\" data-archivo-perfil></div><div class=\"campo-compacta\" data-medidas-compactas hidden>");
  for(String k:List.of("BRAZO","ANTEBRAZO","CUELLO","TRONCO")){
   String img=RecorridoCuerpo.RANGOS.get(Segmento.valueOf(k)).get(0).imagen();h.append("<div class=\"campo-medida\" data-medida=\"").append(k).append("\"><img class=\"campo-silueta\" src=\"/static/img/tour/").append(img).append("\" alt=\"\"><div><span data-angulo=\"").append(k).append("\">Sin medir</span><span class=\"tag\" data-revisar hidden>Revisar</span>");String[][] opciones=RecorridoCuerpo.RANGOS.get(Segmento.valueOf(k)).stream().map(x->new String[]{""+x.grados(),x.etiqueta()}).toArray(String[][]::new);pregunta(h,"rango_"+k,"",nombre(k),"",opciones);h.append("</div></div>");
  }
  h.append("<div class=\"campo-ajustes\"><span class=\"eyebrow\">Míralo</span><h3>Marca lo que veas</h3><div class=\"campo-chips\">");
  for(var x:new String[][]{{"hombroElevado","Hombro subido"},{"brazoSeparado","Brazo separado del cuerpo"},{"brazoApoyado","Brazo apoyado"},{"antebrazoCruza","Antebrazo cruza el cuerpo o sale hacia un lado"},{"cuello_campo","Cabeza torcida o inclinada"},{"tronco_campo","Espalda torcida o inclinada"},{"pies_sin_apoyo","Pies sin buen apoyo"}})chip(h,x[0],x[1]);h.append("</div>");detalle(h,"cuello_tipo","cuello_campo");detalle(h,"tronco_tipo","tronco_campo");h.append("<p>Si no marcas nada, se cuenta como que no hay ajuste.</p>");
  h.append("<fieldset class=\"campo-muneca\"><legend>Muñeca</legend><input type=\"hidden\" name=\"muneca_campo\"><div class=\"campo-chips\">");for(var x:new String[][]{{"RECTA","Recta"},{"POCO","Un poco doblada"},{"MUCHO","Muy doblada"}})h.append("<button type=\"button\" class=\"campo-chip\" data-muneca=\"").append(MapeosCampo.MUNECA.get(x[0])).append("\" aria-pressed=\"false\">").append(x[1]).append("</button>");chip(h,"munecaDesviada","Torcida hacia un lado");chip(h,"giro_extremo","Giro hasta el límite");h.append("</div></fieldset></div></div></div></div>").append(apoyo("frente","De frente y con el cuerpo completo.","FRENTE")).append(apoyo("detalle","La mano y la muñeca de cerca. Solo sirve de evidencia.","OTRA")).append("</section>");
  abrir(h,6,"Carga");String[][] pesos={{"NADA","Nada de peso"},{"CELULAR","Menos de 2 kg (como un celular)"},{"GALON","De 2 a 10 kg (como un galón de agua)"},{"BULTO","Más de 10 kg (como un bulto)"}};pregunta(h,"peso_campo","Pregúntale","Lo más pesado que levanta o mueve en su turno, ¿se parece más a un celular, a un galón de agua o a un bulto?","Piensa en lo más pesado de esta tarea.",pesos);pregunta(h,"esfuerzo_opcion","Pregúntale","Esa postura, ¿la mantiene quieta por más de un minuto, o repite el mismo movimiento más de cuatro veces por minuto?","Puedes observar un minuto con el reloj.",new String[][]{{"NINGUNA","Ninguna, es de vez en cuando"},{"ESTATICA","La mantiene quieta"},{"REPETITIVA","La repite mucho"}});siNo(h,"golpe_campo","Pregúntale","¿La herramienta o la pieza le ha dado alguna vez un tirón o un golpe seco en la mano o en el brazo?");h.append("<div data-mapeos hidden>");for(String peso:List.of("NADA","CELULAR","GALON","BULTO"))for(String act:List.of("NINGUNA","ESTATICA","REPETITIVA"))for(boolean golpe:new boolean[]{false,true})h.append("<i data-peso=\"").append(peso).append("\" data-actividad=\"").append(act).append("\" data-golpe=\"").append(golpe?"si":"no").append("\" data-carga=\"").append(MapeosCampo.carga(peso,act,golpe).name()).append("\"></i>");for(String parte:List.of("cuello","tronco"))for(String tipo:List.of("GIRADA","INCLINADA","AMBAS")){var valores=MapeosCampo.orientacion("si",tipo);h.append("<i data-orientacion=\"").append(parte).append("\" data-tipo=\"").append(tipo).append("\" data-girada=\"").append(valores[0]).append("\" data-inclinada=\"").append(valores[1]).append("\"></i>");}for(var e:MapeosCampo.CRITERIOS.entrySet())h.append("<i data-momento=\"").append(e.getKey()).append("\" data-criterio=\"").append(e.getValue()).append("\"></i>");h.append("</div></section>");
  abrir(h,7,"Resultado");h.append("<h3 data-resumen-titulo hidden>Resumen del puesto</h3><div data-resultados></div><button class=\"btn p\" type=\"button\" data-postura-siguiente hidden>Siguiente: postura 2 de 2</button></section><div class=\"aviso\" role=\"alert\" data-error-evaluacion hidden><span></span><button type=\"button\" class=\"link\" data-cerrar-error>Cerrar</button></div><div class=\"wizfoot\"><p class=\"hint\" role=\"status\" data-falta></p><button type=\"button\" class=\"btn p\" data-siguiente>Seguir →</button><button type=\"submit\" class=\"btn p\" data-guardar-volver hidden>Guardar y terminar</button><button type=\"submit\" class=\"link\" data-agregar-postura hidden>Agregar otra postura</button></div><div data-editor-compatibilidad hidden>");String editor=PaginasAnalisis.pasos();h.append(editor.substring(0,editor.indexOf("<section class=\"card stack\" data-paso=\"6\"")).replace("data-paso=","data-editor-paso=")).append("</div></form>").append(PaginasAnalisis.scripts());return Html.pagina("Nueva evaluación",PaginasEvaluacion.fases(h.toString()),s,false,false);
 }
 private static void oculto(StringBuilder h,String n,String v){h.append("<input type=\"hidden\" name=\"").append(n).append("\" value=\"").append(escapar(v)).append("\">");}
 private static void abrir(StringBuilder h,int n,String t){
  h.append("<section class=\"card stack conversacion-pantalla\" data-paso=\"").append(n).append("\"").append(n==1?"":" hidden").append("><div class=\"campo-titulo\"><h2>").append(t).append("</h2></div>");
  if(n>=5)h.append("<div class=\"campo-postura-aviso\" role=\"status\" data-postura-aviso></div><button type=\"button\" class=\"link\" data-cambiar-lado hidden>Cambiar lado</button>");
 }
 private static void chip(StringBuilder h,String nombre,String texto){h.append("<label class=\"campo-chip\"><input type=\"checkbox\" data-chip=\"").append(nombre).append("\"><span>").append(texto).append("</span></label>");}
 private static void siNo(StringBuilder h,String n,String voz,String t){pregunta(h,n,voz,t,"",new String[][]{{"si","Sí"},{"no","No"}});}
 private static void detalle(StringBuilder h,String n,String depende){int inicio=h.length();pregunta(h,n,"","¿Cómo está: girada, inclinada o las dos?","Así registramos solo lo que ves, sin sumar dos cambios por uno solo.",new String[][]{{"GIRADA","Girada"},{"INCLINADA","Inclinada hacia un lado"},{"AMBAS","Las dos"}});h.insert(inicio+"<div".length()," data-cuando=\""+depende+"\"");}
 private static void pregunta(StringBuilder h,String n,String voz,String t,String ejemplo,String[][] opciones){h.append("<div class=\"campo-pregunta\" data-pregunta=\"").append(n).append("\">");if(!voz.isEmpty())h.append("<span class=\"eyebrow\">").append(voz).append("</span>");h.append("<p id=\"pregunta-").append(n).append("\"><em>“").append(t).append("”</em></p>");h.append("<input type=\"hidden\" name=\"").append(n).append("\"><button class=\"campo-respuesta\" type=\"button\" aria-expanded=\"false\" aria-controls=\"opciones-").append(n).append("\" aria-labelledby=\"pregunta-").append(n).append(" respuesta-").append(n).append("\" data-abrir=\"").append(n).append("\"><span id=\"respuesta-").append(n).append("\">Elige una opción</span><span aria-hidden=\"true\">⌄</span></button><div class=\"campo-lista\" id=\"opciones-").append(n).append("\" hidden>");for(var x:opciones){h.append("<button type=\"button\" class=\"campo-opcion\" data-respuesta=\"").append(n).append("\" data-valor=\"").append(escapar(x[0])).append("\" aria-pressed=\"false\">");if(x.length>2)h.append("<img src=\"/static/img/tour/").append(x[2]).append("\" alt=\"\">");h.append("<span>").append(escapar(x[1])).append("</span></button>");}h.append("</div></div>");}
 private static String muestra(String tipo,String leyenda){return "<figure class=\"campo-muestra\"><img src=\"/static/img/muestra_"+tipo+".jpg\" alt=\"Ejemplo de foto de "+tipo+"\">"+(leyenda.isEmpty()?"":"<figcaption>"+leyenda+"</figcaption>")+"</figure>";}
 private static String apoyo(String tipo,String leyenda,String vista){return "<details class=\"campo-apoyo\"><summary>Agregar foto de "+(tipo.equals("detalle")?"detalle de mano":"frente")+" (opcional)</summary>"+muestra(tipo,leyenda)+"<button type=\"button\" class=\"btn\" data-agregar=\""+vista+"\">Subir foto</button>"+GaleriaDemo.selector(vista)+"<input type=\"file\" hidden accept=\"image/jpeg,image/png\" data-archivo-extra=\""+vista+"\"><div data-apoyo-vista=\""+vista+"\"></div></details>";}
 private static String nombre(String k){return switch(k){case "ANTEBRAZO"->"Antebrazo";case "CUELLO"->"Cuello";case "TRONCO"->"Tronco";default->"Brazo";};}
 private static String preguntaAngulo(String k){return switch(k){case "ANTEBRAZO"->"¿Qué tan doblado está el codo?";case "CUELLO"->"¿Qué tan inclinada está la cabeza hacia adelante?";case "TRONCO"->"¿Qué tan inclinada está la espalda?";default->"¿Qué tan levantado está el brazo?";};}
 static String continuar(Sesion s,Evaluaciones.Consulta c){var f=c.ficha();var d=f.datos();var p=new Puesto(f.puesto(),0,null,null,f.numero(),d.postura(),"","",null,true);String html=pagina(s,List.of(p),p.id(),f.visita(),"Evaluación existente · Puesto "+f.numero());html=html.replace("action=\"/evaluaciones\"","data-criterio=\""+escapar(d.criterio())+"\" data-continuar=\""+f.id()+"\" action=\"/evaluaciones/"+f.id()+"/analisis\"");StringBuilder fotos=new StringBuilder("<div data-fotos-existentes hidden>");for(var foto:c.fotos())fotos.append("<span data-foto-id=\"").append(foto.id()).append("\" data-vista=\"").append(foto.vista()).append("\" data-descripcion=\"").append(escapar(foto.descripcion())).append("\" data-src=\"/fotos/").append(foto.id()).append("\"></span>");return html.replace("</form>",fotos.append("</div></form>").toString());}
}
